from __future__ import annotations

"""
GROUP-MEDIAN TEMPORAL-COUPLING ANALYSIS — SELF-CONTAINED PUBLIC RELEASE
===============================================================================

This public-release script reproduces the complementary group-median temporal-
coupling analysis while keeping participant identifiers and the study-specific
participant-overlap pattern outside the public repository.

Participant dependence
----------------------
Two generic resampling designs are implemented:

1) ``independent_modalities``
   Neural and behavioral observations use separate matching namespaces.
   Repeated-participant dependence within each modality is determined only from
   local pseudonymous matching IDs.

2) ``matched_modalities``
   A common matching namespace is used when neural and behavioral
   observations belong to the same resampling units.

The public file contains no participant list and does not hard-code which Study-1
neural datasets overlap. Matching is supplied locally at runtime through a
local JSON file or JSON environment variable. If that local configuration changes,
clear the local pairwise/resampling caches before rerunning. Matching IDs are never
persisted by this public-release script.

Participant configuration
---------------------------------
Set ``VISC_PARTICIPANT_CONFIG_PATH`` to a local JSON file kept outside the
repository (or listed in ``.gitignore``), or set ``VISC_PARTICIPANT_CONFIG_JSON``
directly. Expected schema (illustrative labels only; no real IDs are included):

{
  "study1": {
    "mode": "independent_modalities",
    "neural_ids": {
      "movieTP": ["<local neural matching IDs>"],
      "movieDM": ["<local neural matching IDs>"],
      "movieBD": ["<local neural matching IDs>"]
    },
    "behavior_ids": {
      "movieTP": {"valence": ["<local rater IDs>"], "arousal": ["<local rater IDs>"]},
      "movieDM": {"valence": ["<local rater IDs>"], "arousal": ["<local rater IDs>"]},
      "movieBD": {"valence": ["<local rater IDs>"], "arousal": ["<local rater IDs>"]}
    }
  },
  "study2": {
    "mode": "matched_modalities",
    "common_ids": ["<matched participant IDs>"]
  }
}

Matching IDs may be arbitrary pseudonyms. They are used only to preserve
resampling dependencies. Raw IDs and ID-derived fingerprints are not written to this script's
resampling metadata. Participant matching remains local to the local runtime
configuration.

Outputs
-------
Study 1
    - dataset-specific marginal valence and arousal effects
    - covariance-aware GLS pooled Study-1 valence and arousal effects
    - conditional valence controlling arousal
    - valence-minus-arousal Fisher-z contrasts

Study 2
    - session-specific marginal valence and fear effects
    - covariance-aware GLS pooled Study-2 valence and fear effects

Across studies
    - covariance-aware GLS pooled valence effect across all five observed
      stimulus/session datasets

Estimand
--------
For each dataset x affect combination, the effect is the partial correlation
across sliding windows between group-median neural DMN ISC and group-median
affective ISC, controlling audiovisual covariates and linear/quadratic time.
Dataset/session effects are Fisher-z transformed before GLS pooling.

Multiple comparisons
--------------------
Final FDR families match the manuscript/Supplementary Information:
    - Study 1 pooled marginal valence + arousal: 2 tests
    - Study 1 stimulus-specific marginal effects: 3 datasets x 2 affects
    - Study 2 pooled valence and fear: separate single-test families (q = p)
    - Study 2 session-specific effects: H1/H2 corrected within each affect
    - Study 1 conditional valence: 3 stimulus-specific tests; pooled = single test
    - Study 1 valence-arousal contrast: 3 stimulus-specific tests; pooled = single test
    - all-five pooled valence: single-test family (q = p)

Self-contained release
----------------------
The Study-1 loader, Study-2 loader, and group-median helper routines are embedded
inside this file and materialized to a versioned temporary directory at runtime.
No sibling analysis scripts are required.
"""

