                                                                 '            f"Expected: '
                                                                 '{EXPECTED_ALIGNMENT_VERSION}\\n"\n'
                                                                 '            f"Found:    {actual_version}"\n'
                                                                 '        )\n'
                                                                 '\n'
                                                                 '    OUT_DIR = source.BASE_DIR / '
                                                                 '"Study1_group_median_meta_analysis_joint_sampling_temporal"\n'
