                                                                 'neural+behavior participant bootstrap plus '
                                                                 'intact-block permutation of bootstrapped behavioral '
                                                                 'residuals",\n'
                                                                 '        "duplicate_subject_policy": "bootstrap '
                                                                 'duplicate copies of the same original participant '
                                                                 'are not treated as valid self-pair ISC observations; '
                                                                 'distinct original dyads get weight c_i*c_j",\n'
                                                                 '        "n_joint_resamples": '
                                                                 'int(N_JOINT_RESAMPLES),\n'
                                                                 '        "random_seed": int(RANDOM_SEED),\n'
