def _require_participant_config() -> None:
    """Require a local matching-ID configuration without exposing IDs."""
    raw = os.environ.get(PARTICIPANT_CONFIG_JSON_ENV, "").strip()
    path_value = os.environ.get(PARTICIPANT_CONFIG_PATH_ENV, "").strip()
    if raw and path_value:
        raise ValueError(
            f"Set only one of {PARTICIPANT_CONFIG_JSON_ENV} or "
            f"{PARTICIPANT_CONFIG_PATH_ENV}."
        )
    if not raw and not path_value and DEFAULT_PARTICIPANT_CONFIG.exists():
        os.environ[PARTICIPANT_CONFIG_PATH_ENV] = str(DEFAULT_PARTICIPANT_CONFIG)
        path_value = str(DEFAULT_PARTICIPANT_CONFIG)
    if not raw and not path_value:
        raise FileNotFoundError(
            "A local participant matching configuration is required. Set "
            f"{PARTICIPANT_CONFIG_PATH_ENV} to a JSON file kept outside the public "
            "repository (or create participant_matching_config.json beside this script "
            "and keep it in .gitignore). No participant IDs are distributed here."
        )


def _materialize_embedded_scripts() -> dict[str, Path]:
    """Write embedded helper modules to a versioned temporary cache."""
    digest = hashlib.sha256(
        "\n".join(
            name + "\n" + text for name, text in sorted(EMBEDDED_SCRIPT_TEXT.items())
        ).encode("utf-8")
    ).hexdigest()[:16]
    root = Path(tempfile.gettempdir()) / f"visc_group_median_{digest}"
    root.mkdir(parents=True, exist_ok=True)
    paths = {}
    for name, text in EMBEDDED_SCRIPT_TEXT.items():
        path = root / name
        if not path.exists() or path.read_text(encoding="utf-8") != text:
            path.write_text(text, encoding="utf-8")
        paths[name] = path
    return paths


def _load_python_module(path: Path, name: str) -> ModuleType:
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise ImportError(f"Cannot import embedded script: {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    try:
        spec.loader.exec_module(module)
    except Exception:
        sys.modules.pop(name, None)
        raise
    return module


