def save_json(obj, path: Path) -> None:
    with open(path, "w", encoding="utf-8") as file:
        json.dump(obj, file, ensure_ascii=False, indent=2)


def load_json(path: Path):
    with open(path, "r", encoding="utf-8") as file:
        return json.load(file)


def print_section(title: str, width: int = 116) -> None:
    print("\n" + "=" * width)
    print(title)
    print("=" * width)


def format_elapsed(seconds: float) -> str:
    seconds = max(0.0, float(seconds))
    if seconds < 60:
        return f"{seconds:5.1f}s"
    minutes, seconds = divmod(seconds, 60)
    if minutes < 60:
        return f"{int(minutes):02d}:{seconds:04.1f}"
    hours, minutes = divmod(minutes, 60)
    return f"{int(hours):02d}:{int(minutes):02d}:{seconds:04.1f}"


def print_progress(label: str, current: int, total: int, start: float) -> None:
    elapsed = time.time() - start
    pct = 100.0 * current / max(total, 1)
    eta = elapsed * (total - current) / current if 0 < current < total else 0.0
    message = (
        f"{label} | {current:,}/{total:,} ({pct:6.2f}%) "
        f"| elapsed={format_elapsed(elapsed)}"
    )
    if current < total:
        message += f" | ETA={format_elapsed(eta)}"
    print(f"{message:<175}", end="\n" if current == total else "\r", flush=True)


def two_sided_p(null_values: np.ndarray, observed: float) -> float:
    values = np.asarray(null_values, dtype=float)
    values = values[np.isfinite(values)]
    if len(values) == 0 or not np.isfinite(observed):
        return np.nan
    return float((1 + np.sum(np.abs(values) >= abs(observed))) / (len(values) + 1))


def quantile_ci(values: np.ndarray) -> tuple[float, float]:
    values = np.asarray(values, dtype=float)
    values = values[np.isfinite(values)]
    if len(values) == 0:
        return np.nan, np.nan
    low, high = np.quantile(values, [0.025, 0.975])
    return float(low), float(high)


def bh_adjust(p_values: np.ndarray) -> np.ndarray:
    """Benjamini-Hochberg adjusted p values, preserving NaNs."""
    p = np.asarray(p_values, dtype=float)
    output = np.full_like(p, np.nan, dtype=float)
    valid = np.isfinite(p)
    values = p[valid]
    if len(values) == 0:
        return output
    order = np.argsort(values)
    ranked = values[order]
    m = len(ranked)
    adjusted = ranked * m / np.arange(1, m + 1)
    adjusted = np.minimum.accumulate(adjusted[::-1])[::-1]
    adjusted = np.clip(adjusted, 0.0, 1.0)
    inverse = np.empty_like(order)
    inverse[order] = np.arange(m)
    output[valid] = adjusted[inverse]
    return output


# =============================================================================
# DATA CONTAINER AND CACHE ACCESS
# =============================================================================


class AnalysisData:
    def __init__(
        self,
        s1_prepared: dict,
        s2_prepared: dict,
        observed_neural: dict[str, np.ndarray] | None = None,
        observed_behavior: dict[str, dict[str, np.ndarray]] | None = None,
    ) -> None:
        self.s1_prepared = s1_prepared
        self.s2_prepared = s2_prepared
        self.observed_neural = observed_neural or {}
        self.observed_behavior = observed_behavior or {}


def study1_roi_name(S1: ModuleType) -> str:
    return str(getattr(S1, "ROI_NAME", "DMN"))


def affects_for_dataset(dataset: str) -> list[str]:
    return AFFECTS_BY_STUDY[DATASET_STUDY[dataset]]


def neural_cache(S1: ModuleType, all_data: AnalysisData, dataset: str):
    if dataset in STUDY1_DATASETS:
        return all_data.s1_prepared["neural_caches"][study1_roi_name(S1)][dataset]
    return all_data.s2_prepared["neural_caches"][dataset]


def behavior_cache(all_data: AnalysisData, dataset: str, affect: str):
    if affect not in affects_for_dataset(dataset):
        raise KeyError(f"{dataset} has no requested affect cache: {affect}")
    if dataset in STUDY1_DATASETS:
        return all_data.s1_prepared["behavior_caches"][dataset][affect]
    return all_data.s2_prepared["behavior_caches"][dataset][affect]


def covariate_table(all_data: AnalysisData, dataset: str) -> pd.DataFrame:
    if dataset in STUDY1_DATASETS:
        return all_data.s1_prepared["covariates"][dataset].copy()
    return all_data.s2_prepared["covariates"][dataset].copy()


def validate_sources(M: ModuleType, S1: ModuleType, S2: ModuleType) -> None:
    if getattr(S1, "CHEN_ALIGNMENT_POLICY_VERSION", None) != EXPECTED_STUDY1_ALIGNMENT_VERSION:
        raise RuntimeError(
            "Unexpected Study 1 alignment version.\n"
            f"Expected: {EXPECTED_STUDY1_ALIGNMENT_VERSION}\n"
            f"Found:    {getattr(S1, 'CHEN_ALIGNMENT_POLICY_VERSION', None)}"
        )
    if getattr(S2, "CHEN_ALIGNMENT_POLICY_VERSION", None) != EXPECTED_STUDY2_ALIGNMENT_VERSION:
        raise RuntimeError(
            "Unexpected Study 2 alignment version.\n"
            f"Expected: {EXPECTED_STUDY2_ALIGNMENT_VERSION}\n"
            f"Found:    {getattr(S2, 'CHEN_ALIGNMENT_POLICY_VERSION', None)}"
        )
    if Path(S1.BASE_DIR) != Path(S2.BASE_DIR):
        raise ValueError(
            "Study 1 and Study 2 BASE_DIR values differ:\n"
            f"Study 1: {S1.BASE_DIR}\nStudy 2: {S2.BASE_DIR}"
        )
    if list(getattr(S1, "MODEL_COVARIATES", MODEL_COVARIATES)) != MODEL_COVARIATES:
        raise RuntimeError("Study 1 MODEL_COVARIATES differ from expected covariates")
    if list(getattr(S2, "MODEL_COVARIATES", MODEL_COVARIATES)) != MODEL_COVARIATES:
        raise RuntimeError("Study 2 MODEL_COVARIATES differ from expected covariates")
    if getattr(S1, "DEPENDENCE_MODE", None) != "independent_modalities":
        raise RuntimeError("Embedded Study 1 source is not in independent_modalities mode")
    if getattr(S2, "DEPENDENCE_MODE", None) != "matched_modalities":
        raise RuntimeError("Embedded Study 2 source is not in matched_modalities mode")

    required_helpers = [
        "precompute_sorted_median_cache",
        "observed_median_from_sorted",
        "weighted_median_trajectory",
        "draw_multinomial_counts",
        "master_to_target_indices",
        "random_block_indices",
        "estimate_acf_length",
        "zscore_1d",
        "residualize",
        "pearson_r",
        "fisher_z_from_r",
        "r_from_fisher_z",
    ]
    missing = [name for name in required_helpers if not hasattr(M, name)]
    if missing:
        raise RuntimeError(
            "The Study-1 group-median meta helper script is missing required helpers: "
            + ", ".join(missing)
        )


def validate_prepared_data(S1: ModuleType, all_data: AnalysisData) -> pd.DataFrame:
    rows = []
    for dataset in DATASETS:
        nc = neural_cache(S1, all_data, dataset)
        table = covariate_table(all_data, dataset)
        n_neural = int(nc["n_windows"])
        n_covariate = int(len(table))
        if n_neural != n_covariate:
            raise ValueError(
                f"{dataset}: neural windows={n_neural}, covariate rows={n_covariate}"
            )

        row = {
            "study": DATASET_STUDY[dataset],
            "dataset": dataset,
            "label": DATASET_LABELS[dataset],
            "n_neural_subjects": len(nc["subject_ids"]),
            "n_windows": n_neural,
        }
        for affect in affects_for_dataset(dataset):
            bc = behavior_cache(all_data, dataset, affect)
            n_behavior = int(bc["n_windows"])
            if n_behavior != n_neural:
                raise ValueError(
                    f"{dataset}-{affect}: behavior windows={n_behavior}, neural windows={n_neural}"
                )
            row[f"n_{affect}_subjects"] = len(bc["subject_ids"])
        missing_covs = [col for col in MODEL_COVARIATES if col not in table.columns]
        if missing_covs:
            raise ValueError(f"{dataset}: missing covariates {missing_covs}")
        rows.append(row)

    # Study-1 neural dependence is inferred later from matching IDs.
    # No dataset-overlap pattern is hard-coded in this public release.

    # Study-2 neural and both affect caches must share the common matched order.
    common_ids = np.asarray(all_data.s2_prepared["common_ids"], dtype=str)
    for dataset in STUDY2_DATASETS:
        caches = [("neural", all_data.s2_prepared["neural_caches"][dataset])]
        caches.extend(
            (affect, all_data.s2_prepared["behavior_caches"][dataset][affect])
            for affect in ["valence", "fear"]
        )
        for label, cache in caches:
            ids = np.asarray(cache["subject_ids"], dtype=str)
            if not np.array_equal(ids, common_ids):
                raise ValueError(
                    f"{dataset} {label} cache IDs/order differ from Study-2 common_ids"
                )

    return pd.DataFrame(rows)


# =============================================================================
# OBSERVED EFFECTS
# =============================================================================


def prepare_sorted_caches(
    M: ModuleType,
    S1: ModuleType,
    all_data: AnalysisData,
) -> dict[str, object]:
    sorted_neural = {
        dataset: M.precompute_sorted_median_cache(neural_cache(S1, all_data, dataset))
        for dataset in DATASETS
    }
    sorted_behavior = {
        dataset: {
            affect: M.precompute_sorted_median_cache(
                behavior_cache(all_data, dataset, affect)
            )
            for affect in affects_for_dataset(dataset)
        }
        for dataset in DATASETS
    }
    return {"neural": sorted_neural, "behavior": sorted_behavior}


def assemble_dataset_table(
    M: ModuleType,
    all_data: AnalysisData,
    dataset: str,
    neural_trajectory: np.ndarray,
    behavior_trajectories: dict[str, np.ndarray],
) -> pd.DataFrame:
    table = covariate_table(all_data, dataset)
    expected_n = len(table)
    if len(neural_trajectory) != expected_n:
        raise ValueError(
            f"{dataset}: neural trajectory has {len(neural_trajectory)} windows; expected {expected_n}"
        )
    table["z_neural_ISC"] = M.zscore_1d(neural_trajectory)

    for affect in affects_for_dataset(dataset):
        values = behavior_trajectories[affect]
        if len(values) != expected_n:
            raise ValueError(
                f"{dataset}-{affect}: trajectory has {len(values)} windows; expected {expected_n}"
            )
        table[f"z_{affect}_ISC"] = M.zscore_1d(values)

    table["dataset"] = dataset
    return table


def marginal_effect_from_table(
    M: ModuleType,
    table: pd.DataFrame,
    affect: str,
) -> dict[str, object]:
    controls = table[MODEL_COVARIATES].to_numpy(float)
    neural = table["z_neural_ISC"].to_numpy(float)
    predictor = table[f"z_{affect}_ISC"].to_numpy(float)

    y_res_full = M.residualize(neural, controls)
    x_res_full = M.residualize(predictor, controls)
    valid = np.isfinite(y_res_full) & np.isfinite(x_res_full)
    if int(valid.sum()) < 4:
        return {
            "r": np.nan,
            "z": np.nan,
            "x_res": np.asarray([], dtype=float),
            "y_res": np.asarray([], dtype=float),
            "n_windows": int(valid.sum()),
        }

    x_res = np.asarray(x_res_full[valid], dtype=float)
    y_res = np.asarray(y_res_full[valid], dtype=float)
    r = M.pearson_r(y_res, x_res)
    return {
        "r": r,
        "z": M.fisher_z_from_r(r),
        "x_res": x_res,
        "y_res": y_res,
        "n_windows": int(valid.sum()),
    }


def study1_conditional_valence_detail(
    M: ModuleType,
    table: pd.DataFrame,
) -> dict[str, object]:
    """Study-1 conditional valence effect: valence controlling arousal + nuisances."""
    base_controls = table[MODEL_COVARIATES].to_numpy(float)
    arousal = table["z_arousal_ISC"].to_numpy(float)
    controls = np.column_stack([base_controls, arousal])
    neural = table["z_neural_ISC"].to_numpy(float)
    valence = table["z_valence_ISC"].to_numpy(float)

    y_res_full = M.residualize(neural, controls)
    x_res_full = M.residualize(valence, controls)
    valid = np.isfinite(y_res_full) & np.isfinite(x_res_full)
    if int(valid.sum()) < 4:
        return {
            "r": np.nan,
            "z": np.nan,
            "x_res": np.asarray([], dtype=float),
            "y_res": np.asarray([], dtype=float),
            "n_windows": int(valid.sum()),
        }

    x_res = np.asarray(x_res_full[valid], dtype=float)
    y_res = np.asarray(y_res_full[valid], dtype=float)
    r = M.pearson_r(y_res, x_res)
    return {
        "r": r,
        "z": M.fisher_z_from_r(r),
        "x_res": x_res,
        "y_res": y_res,
        "n_windows": int(valid.sum()),
    }


def calculate_study1_extra_effects(
    M: ModuleType,
    tables: dict[str, pd.DataFrame],
) -> tuple[np.ndarray, dict[str, dict[str, dict[str, object]]]]:
    """
    Compute Study-1-only conditional valence and valence-minus-arousal contrast.

    Returns
    -------
    effects : ndarray, shape (2, 3)
        Row 0 = conditional valence Fisher-z effects for TP/DM/BD.
        Row 1 = marginal valence-minus-arousal Fisher-z differences for TP/DM/BD.
    details : dict
        Residual details for conditional valence and marginal components.
    """
    effects = np.empty((len(S1_EXTRA_FAMILIES), len(STUDY1_DATASETS)), dtype=float)
    details: dict[str, dict[str, dict[str, object]]] = {
        family: {} for family in S1_EXTRA_FAMILIES
    }

    for dataset in STUDY1_DATASETS:
        j = S1_DATASET_INDEX[dataset]
        table = tables[dataset]

        conditional = study1_conditional_valence_detail(M, table)
        effects[S1_EXTRA_INDEX["conditional_valence_given_arousal"], j] = float(
            conditional["z"]
        )
        details["conditional_valence_given_arousal"][dataset] = conditional

        valence = marginal_effect_from_table(M, table, "valence")
        arousal = marginal_effect_from_table(M, table, "arousal")
        contrast_z = float(valence["z"] - arousal["z"])
        effects[S1_EXTRA_INDEX["marginal_valence_minus_arousal"], j] = contrast_z
        details["marginal_valence_minus_arousal"][dataset] = {
            "z": contrast_z,
            "valence": valence,
            "arousal": arousal,
            "n_windows": int(min(valence["n_windows"], arousal["n_windows"])),
        }

    return effects, details


def permuted_study1_extra_effects(
    M: ModuleType,
    extra_details: dict[str, dict[str, dict[str, object]]],
    marginal_null_effects: np.ndarray,
    block_indices_for_draw: dict[str, np.ndarray],
    block_lengths: dict[str, int],
    draw_index: int,
) -> np.ndarray:
    """Joint temporal null for Study-1-only conditional and contrast families."""
    output = np.empty((len(S1_EXTRA_FAMILIES), len(STUDY1_DATASETS)), dtype=float)

    # Conditional valence: permute the residualized valence trajectory using the
    # same movie-specific block order as the marginal analyses.
    family = "conditional_valence_given_arousal"
    fi = S1_EXTRA_INDEX[family]
    for dataset in STUDY1_DATASETS:
        j = S1_DATASET_INDEX[dataset]
        detail = extra_details[family][dataset]
        x = np.asarray(detail["x_res"], dtype=float)
        y = np.asarray(detail["y_res"], dtype=float)
        order = np.asarray(block_indices_for_draw[dataset], dtype=np.int32)
        if len(order) != len(x):
            fallback_rng = np.random.default_rng(
                RANDOM_SEED + 1_100_000 + draw_index * len(STUDY1_DATASETS) + j
            )
            order = M.random_block_indices(
                len(x), int(block_lengths[dataset]), fallback_rng
            )
        output[fi, j] = M.fisher_z_from_r(M.pearson_r(y, x[order]))

    # Contrast: paired difference of the marginal valence and arousal null
    # effects generated with the same participant draw and same block order.
    fi = S1_EXTRA_INDEX["marginal_valence_minus_arousal"]
    for dataset in STUDY1_DATASETS:
        j = S1_DATASET_INDEX[dataset]
        z_val = marginal_null_effects[EFFECT_INDEX[(dataset, "valence")]]
        z_aro = marginal_null_effects[EFFECT_INDEX[(dataset, "arousal")]]
        output[fi, j] = float(z_val - z_aro)

    return output


def calculate_effects(
    M: ModuleType,
    all_data: AnalysisData,
    neural_override: dict[str, np.ndarray] | None = None,
    behavior_override: dict[str, dict[str, np.ndarray]] | None = None,
) -> tuple[np.ndarray, dict[tuple[str, str], dict[str, object]], dict[str, pd.DataFrame]]:
    neural_override = neural_override or {}
    behavior_override = behavior_override or {}

    effects = np.empty(len(EFFECT_KEYS), dtype=float)
    details: dict[tuple[str, str], dict[str, object]] = {}
    tables: dict[str, pd.DataFrame] = {}

    for dataset in DATASETS:
        neural = neural_override.get(dataset, all_data.observed_neural[dataset])
        behavior = {
            affect: behavior_override.get(dataset, {}).get(
                affect, all_data.observed_behavior[dataset][affect]
            )
            for affect in affects_for_dataset(dataset)
        }
        table = assemble_dataset_table(M, all_data, dataset, neural, behavior)
        tables[dataset] = table
        for affect in affects_for_dataset(dataset):
            key = (dataset, affect)
            detail = marginal_effect_from_table(M, table, affect)
            details[key] = detail
            effects[EFFECT_INDEX[key]] = float(detail["z"])

    return effects, details, tables


# =============================================================================
# ACF-INFORMED BLOCK LENGTHS
# =============================================================================


def prepare_block_lengths(
    M: ModuleType,
    observed_details: dict[tuple[str, str], dict[str, object]],
    observed_tables: dict[str, pd.DataFrame],
) -> tuple[dict[str, int], pd.DataFrame]:
    """
    Select one common block length per dataset.

    Study 1: maximum ACF lag across marginal valence, marginal arousal, and
    conditional-valence behavior/neural residuals, matching the original
    Study-1 complementary meta-analysis logic.

    Study 2: maximum ACF lag across marginal valence and marginal fear
    behavior/neural residuals.
    """
    block_lengths: dict[str, int] = {}
    rows = []

    for dataset in DATASETS:
        lengths = []
        for affect in affects_for_dataset(dataset):
            detail = observed_details[(dataset, affect)]
            x_len = int(M.estimate_acf_length(detail["x_res"], ACF_THRESHOLD))
            y_len = int(M.estimate_acf_length(detail["y_res"], ACF_THRESHOLD))
            lengths.extend([x_len, y_len])
            rows.extend([
                {
                    "study": DATASET_STUDY[dataset],
                    "dataset": dataset,
                    "label": DATASET_LABELS[dataset],
                    "family": f"marginal_{affect}",
                    "series": "behavior_residual",
                    "acf_length": x_len,
                },
                {
                    "study": DATASET_STUDY[dataset],
                    "dataset": dataset,
                    "label": DATASET_LABELS[dataset],
                    "family": f"marginal_{affect}",
                    "series": "neural_residual",
                    "acf_length": y_len,
                },
            ])

        if dataset in STUDY1_DATASETS:
            conditional = study1_conditional_valence_detail(M, observed_tables[dataset])
            x_len = int(M.estimate_acf_length(conditional["x_res"], ACF_THRESHOLD))
            y_len = int(M.estimate_acf_length(conditional["y_res"], ACF_THRESHOLD))
            lengths.extend([x_len, y_len])
            rows.extend([
                {
                    "study": "Study1",
                    "dataset": dataset,
                    "label": DATASET_LABELS[dataset],
                    "family": "conditional_valence_given_arousal",
                    "series": "behavior_residual",
                    "acf_length": x_len,
                },
                {
                    "study": "Study1",
                    "dataset": dataset,
                    "label": DATASET_LABELS[dataset],
                    "family": "conditional_valence_given_arousal",
                    "series": "neural_residual",
                    "acf_length": y_len,
                },
            ])

        selected = int(max(lengths))
        block_lengths[dataset] = selected
        rows.append({
            "study": DATASET_STUDY[dataset],
            "dataset": dataset,
            "label": DATASET_LABELS[dataset],
            "family": "common_maximum",
            "series": "selected_block_length",
            "acf_length": selected,
        })

    return block_lengths, pd.DataFrame(rows)


# =============================================================================
# JOINT PARTICIPANT + TEMPORAL RESAMPLING PLAN
# =============================================================================


def _study1_neural_dependency_groups(S1: ModuleType, all_data: AnalysisData):
    """Infer exact-set neural dependency groups from pseudonymous IDs.

    Datasets with identical participant sets share one bootstrap draw. Disjoint
    sets are independent. Partial-but-nonidentical overlap is rejected because
    it requires a design-specific coupling rule rather than an implicit guess.
    """
    roi = study1_roi_name(S1)
    dataset_ids = {
        dataset: np.asarray(
            all_data.s1_prepared["neural_caches"][roi][dataset]["subject_ids"],
            dtype=str,
        )
        for dataset in STUDY1_DATASETS
    }
    for i, left in enumerate(STUDY1_DATASETS):
        left_set = set(map(str, dataset_ids[left]))
        for right in STUDY1_DATASETS[i + 1:]:
            right_set = set(map(str, dataset_ids[right]))
            overlap = left_set & right_set
            if overlap and left_set != right_set:
                raise ValueError(
                    "Study-1 neural datasets contain partial but non-identical "
                    f"participant overlap ({left} vs {right}). This generic public "
                    "release does not infer a coupling rule for partial overlap. "
                    "Provide a design-specific resampling rule locally. Participant "
                    "identifiers are not printed."
                )

    grouped = {}
    for dataset, ids in dataset_ids.items():
        grouped.setdefault(frozenset(map(str, ids)), []).append(dataset)

    groups = []
    for member_set, datasets in grouped.items():
        canonical = np.asarray(sorted(member_set), dtype=str)
        lookup = {sid: idx for idx, sid in enumerate(canonical)}
        mappings = {
            dataset: np.asarray([lookup[str(sid)] for sid in dataset_ids[dataset]], dtype=np.int32)
            for dataset in datasets
        }
        groups.append({
            "canonical_ids": canonical,
            "datasets": tuple(datasets),
            "mappings": mappings,
        })
    return dataset_ids, groups


def generate_joint_plan(
    M: ModuleType,
    S1: ModuleType,
    all_data: AnalysisData,
    block_lengths: dict[str, int],
) -> dict[str, object]:
    assert DRAW_DIR is not None

    s1_dataset_ids, s1_neural_groups = _study1_neural_dependency_groups(S1, all_data)
    s1_master_ids = np.asarray(all_data.s1_prepared["behavior_master_ids"], dtype=str)
    n_s1_behavior = len(s1_master_ids)
    n_s2_common = len(all_data.s2_prepared["common_ids"])

    s1_behavior_target_indices = {
        dataset: {
            affect: M.master_to_target_indices(
                s1_master_ids,
                np.asarray(
                    all_data.s1_prepared["behavior_caches"][dataset][affect]["subject_ids"],
                    dtype=str,
                ),
            )
            for affect in ["valence", "arousal"]
        }
        for dataset in STUDY1_DATASETS
    }

    plan_path = DRAW_DIR / "AllAffects_group_median_joint_plan.npz"
    metadata_path = DRAW_DIR / "AllAffects_group_median_joint_plan.json"
    expected = {
        "n_joint_resamples": int(N_JOINT_RESAMPLES),
        "seed_s1": int(RANDOM_SEED + 50_000),
        "seed_s2": int(RANDOM_SEED + 60_000),
        "seed_time": int(RANDOM_SEED + 70_000),
        "seed_cross_study_pairing": int(RANDOM_SEED + 80_000),
        "study1_mode": "independent_modalities",
        "study2_mode": "matched_modalities",
        "n_s1_neural_dependency_groups": int(len(s1_neural_groups)),
        "s1_neural_dataset_n": {
            dataset: int(len(s1_dataset_ids[dataset])) for dataset in STUDY1_DATASETS
        },
        "n_s1_behavior_master": int(n_s1_behavior),
        "n_s2_common": int(n_s2_common),
        "block_lengths": {dataset: int(block_lengths[dataset]) for dataset in DATASETS},
        "effect_keys": [[dataset, affect] for dataset, affect in EFFECT_KEYS],
        "method": (
            "Study1 independent neural/behavior namespaces; exact-set neural "
            "dependency groups inferred from pseudonymous IDs; one "
            "behavior master-ID bootstrap mapped across Study1 datasets/affects; "
            "Study2 one matched count vector across sessions/modalities/affects; "
            "one common block order per dataset across affects; independent "
            "cross-study pairing"
        ),
        "participant_information": "participant IDs and ID-derived fingerprints omitted; reset cached plans if the local configuration changes",
    }

    if RESUME and plan_path.exists() and metadata_path.exists():
        if load_json(metadata_path) == expected:
            loaded = np.load(plan_path)
            print("[JOINT PLAN LOAD] using existing dependency-aware all-affects plan")
            return {
                "s1_neural_by_dataset": {
                    dataset: loaded[f"s1_neural__{dataset}"] for dataset in STUDY1_DATASETS
                },
                "s1_behavior_weights": loaded["s1_behavior_weights"],
                "s2_common_weights": loaded["s2_common_weights"],
                "block_indices": {
                    dataset: loaded[f"block_indices_{dataset}"] for dataset in DATASETS
                },
                "cross_study_pairing": loaded["cross_study_pairing"],
                "s1_behavior_target_indices": s1_behavior_target_indices,
            }

    rng_s1 = np.random.default_rng(RANDOM_SEED + 50_000)
    rng_s2 = np.random.default_rng(RANDOM_SEED + 60_000)
    rng_time = np.random.default_rng(RANDOM_SEED + 70_000)
    rng_pair = np.random.default_rng(RANDOM_SEED + 80_000)

    s1_neural_by_dataset = {
        dataset: np.empty(
            (N_JOINT_RESAMPLES, len(s1_dataset_ids[dataset])), dtype=np.int16
        )
        for dataset in STUDY1_DATASETS
    }
    s1_behavior_weights = np.empty((N_JOINT_RESAMPLES, n_s1_behavior), dtype=np.int16)
    s2_common_weights = np.empty((N_JOINT_RESAMPLES, n_s2_common), dtype=np.int16)
    block_indices = {
        dataset: np.empty(
            (N_JOINT_RESAMPLES, len(covariate_table(all_data, dataset))),
            dtype=np.int16,
        )
        for dataset in DATASETS
    }

    start = time.time()
    for draw in range(N_JOINT_RESAMPLES):
        for group in s1_neural_groups:
            counts = M.draw_multinomial_counts(rng_s1, len(group["canonical_ids"]))
            for dataset in group["datasets"]:
                s1_neural_by_dataset[dataset][draw] = counts[group["mappings"][dataset]]

        # Study-1 behavioral namespace is independent of neural sampling. A
        # single master-rater draw preserves repeated-rater dependence across
        # datasets and affect dimensions.
        while True:
            candidate = M.draw_multinomial_counts(rng_s1, n_s1_behavior)
            valid = True
            for dataset in STUDY1_DATASETS:
                for affect in ["valence", "arousal"]:
                    indices = s1_behavior_target_indices[dataset][affect]
                    if int(np.count_nonzero(candidate[indices])) < 2:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                s1_behavior_weights[draw] = candidate
                break

        # Study 2 matched-modalities design: one draw is shared across every
        # session, modality, and affective dimension.
        s2_common_weights[draw] = M.draw_multinomial_counts(rng_s2, n_s2_common)

        for dataset in DATASETS:
            n_windows = len(covariate_table(all_data, dataset))
            block_indices[dataset][draw] = M.random_block_indices(
                n_windows,
                int(block_lengths[dataset]),
                rng_time,
            ).astype(np.int16)

        completed = draw + 1
        if completed % max(1, PROGRESS_EVERY) == 0 or completed == N_JOINT_RESAMPLES:
            print_progress(
                "[ALL-AFFECTS JOINT PLAN BUILD]", completed, N_JOINT_RESAMPLES, start
            )

    cross_study_pairing = rng_pair.permutation(N_JOINT_RESAMPLES).astype(np.int32)

    np.savez_compressed(
        plan_path,
        s1_behavior_weights=s1_behavior_weights,
        s2_common_weights=s2_common_weights,
        cross_study_pairing=cross_study_pairing,
        **{
            f"s1_neural__{dataset}": matrix
            for dataset, matrix in s1_neural_by_dataset.items()
        },
        **{f"block_indices_{dataset}": block_indices[dataset] for dataset in DATASETS},
    )
    save_json(expected, metadata_path)

    return {
        "s1_neural_by_dataset": s1_neural_by_dataset,
        "s1_behavior_weights": s1_behavior_weights,
        "s2_common_weights": s2_common_weights,
        "block_indices": block_indices,
        "cross_study_pairing": cross_study_pairing,
        "s1_behavior_target_indices": s1_behavior_target_indices,
    }


# =============================================================================
# TRAJECTORY RECONSTRUCTION + JOINT NULL
# =============================================================================


def trajectories_for_draw(
    M: ModuleType,
    sorted_caches: dict[str, object],
    plan: dict[str, object],
    draw: int,
) -> tuple[dict[str, np.ndarray], dict[str, dict[str, np.ndarray]]]:
    s1_behavior_master = np.asarray(plan["s1_behavior_weights"][draw], dtype=np.int64)
    s2_common = np.asarray(plan["s2_common_weights"][draw], dtype=np.int64)

    neural = {}
    for dataset in STUDY1_DATASETS:
        weights = np.asarray(
            plan["s1_neural_by_dataset"][dataset][draw], dtype=np.int64
        )
        neural[dataset] = M.weighted_median_trajectory(
            sorted_caches["neural"][dataset], weights
        )
    for dataset in STUDY2_DATASETS:
        neural[dataset] = M.weighted_median_trajectory(
            sorted_caches["neural"][dataset], s2_common
        )

    behavior: dict[str, dict[str, np.ndarray]] = {dataset: {} for dataset in DATASETS}

    for dataset in STUDY1_DATASETS:
        for affect in ["valence", "arousal"]:
            target_indices = plan["s1_behavior_target_indices"][dataset][affect]
            target_weights = s1_behavior_master[target_indices]
            behavior[dataset][affect] = M.weighted_median_trajectory(
                sorted_caches["behavior"][dataset][affect],
                target_weights,
            )

    for dataset in STUDY2_DATASETS:
        for affect in ["valence", "fear"]:
            behavior[dataset][affect] = M.weighted_median_trajectory(
                sorted_caches["behavior"][dataset][affect],
                s2_common,
            )

    return neural, behavior


def permuted_effects(
    M: ModuleType,
    details: dict[tuple[str, str], dict[str, object]],
    block_indices_for_draw: dict[str, np.ndarray],
    block_lengths: dict[str, int],
    draw_index: int,
) -> np.ndarray:
    output = np.empty(len(EFFECT_KEYS), dtype=float)

    for key in EFFECT_KEYS:
        dataset, affect = key
        detail = details[key]
        x = np.asarray(detail["x_res"], dtype=float)
        y = np.asarray(detail["y_res"], dtype=float)
        order = np.asarray(block_indices_for_draw[dataset], dtype=np.int32)

        # Rare bootstrap draws can lose one or more windows after residualization.
        # If so, create a deterministic draw-specific fallback permutation using
        # the same dataset block length.
        if len(order) != len(x):
            fallback_rng = np.random.default_rng(
                RANDOM_SEED
                + 900_000
                + draw_index * len(EFFECT_KEYS)
                + EFFECT_INDEX[key]
            )
            order = M.random_block_indices(
                len(x),
                int(block_lengths[dataset]),
                fallback_rng,
            )

        output[EFFECT_INDEX[key]] = M.fisher_z_from_r(
            M.pearson_r(y, x[order])
        )

    return output


def run_joint_resampling(
    M: ModuleType,
    all_data: AnalysisData,
    sorted_caches: dict[str, object],
    plan: dict[str, object],
    block_lengths: dict[str, int],
) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, pd.DataFrame]:
    assert DRAW_DIR is not None

    boot_path = DRAW_DIR / "AllAffects_group_median_participant_bootstrap_effects.npy"
    null_path = DRAW_DIR / "AllAffects_group_median_joint_sampling_temporal_null.npy"
    s1_extra_boot_path = DRAW_DIR / "Study1_conditional_contrast_participant_bootstrap_effects.npy"
    s1_extra_null_path = DRAW_DIR / "Study1_conditional_contrast_joint_sampling_temporal_null.npy"
    progress_path = DRAW_DIR / "AllAffects_group_median_joint_progress.json"
    metadata_path = DRAW_DIR / "AllAffects_group_median_joint_metadata.json"
    expected = {
        "n_joint_resamples": int(N_JOINT_RESAMPLES),
        "effect_keys": [[dataset, affect] for dataset, affect in EFFECT_KEYS],
        "study1_extra_families": S1_EXTRA_FAMILIES,
        "seed": int(RANDOM_SEED),
        "block_lengths": {dataset: int(block_lengths[dataset]) for dataset in DATASETS},
        "method": (
            "exact weighted Pearson-r dyad medians; observed-order neural+behavior "
            "participant bootstrap effects; bootstrapped affect-residual intact-block null; "
            "Study1 conditional valence and paired valence-minus-arousal contrast only"
        ),
    }

    marginal_shape = (N_JOINT_RESAMPLES, len(EFFECT_KEYS))
    extra_shape = (
        N_JOINT_RESAMPLES,
        len(S1_EXTRA_FAMILIES),
        len(STUDY1_DATASETS),
    )

    start_index = 0
    if (
        RESUME
        and boot_path.exists()
        and null_path.exists()
        and s1_extra_boot_path.exists()
        and s1_extra_null_path.exists()
        and progress_path.exists()
        and metadata_path.exists()
        and load_json(metadata_path) == expected
    ):
        boot_draws = np.lib.format.open_memmap(
            boot_path, mode="r+", dtype=np.float64, shape=marginal_shape
        )
        null_draws = np.lib.format.open_memmap(
            null_path, mode="r+", dtype=np.float64, shape=marginal_shape
        )
        s1_extra_boot = np.lib.format.open_memmap(
            s1_extra_boot_path, mode="r+", dtype=np.float64, shape=extra_shape
        )
        s1_extra_null = np.lib.format.open_memmap(
            s1_extra_null_path, mode="r+", dtype=np.float64, shape=extra_shape
        )
        start_index = int(load_json(progress_path).get("completed", 0))
        print(f"[ALL-AFFECTS JOINT RESUME] starting at draw {start_index:,}")
    else:
        boot_draws = np.lib.format.open_memmap(
            boot_path, mode="w+", dtype=np.float64, shape=marginal_shape
        )
        null_draws = np.lib.format.open_memmap(
            null_path, mode="w+", dtype=np.float64, shape=marginal_shape
        )
        s1_extra_boot = np.lib.format.open_memmap(
            s1_extra_boot_path, mode="w+", dtype=np.float64, shape=extra_shape
        )
        s1_extra_null = np.lib.format.open_memmap(
            s1_extra_null_path, mode="w+", dtype=np.float64, shape=extra_shape
        )
        save_json(expected, metadata_path)
        save_json({"completed": 0}, progress_path)

    start = time.time()
    for draw in range(start_index, N_JOINT_RESAMPLES):
        neural, behavior = trajectories_for_draw(M, sorted_caches, plan, draw)
        boot_effects, details, tables = calculate_effects(
            M,
            all_data,
            neural_override=neural,
            behavior_override=behavior,
        )
        boot_extra, extra_details = calculate_study1_extra_effects(M, tables)

        draw_blocks = {
            dataset: np.asarray(plan["block_indices"][dataset][draw], dtype=np.int32)
            for dataset in DATASETS
        }
        null_effects = permuted_effects(
            M,
            details,
            draw_blocks,
            block_lengths,
            draw,
        )
        null_extra = permuted_study1_extra_effects(
            M,
            extra_details,
            null_effects,
            draw_blocks,
            block_lengths,
            draw,
        )

        boot_draws[draw] = boot_effects
        null_draws[draw] = null_effects
        s1_extra_boot[draw] = boot_extra
        s1_extra_null[draw] = null_extra

        completed = draw + 1
        if completed % CHECKPOINT_EVERY == 0 or completed == N_JOINT_RESAMPLES:
            boot_draws.flush()
            null_draws.flush()
            s1_extra_boot.flush()
            s1_extra_null.flush()
            save_json({"completed": completed}, progress_path)
        if completed % max(1, PROGRESS_EVERY) == 0 or completed == N_JOINT_RESAMPLES:
            print_progress(
                "[ALL-AFFECTS NEURAL+BEHAVIOR BOOT + TEMPORAL NULL]",
                completed,
                N_JOINT_RESAMPLES,
                start,
            )

    boot = np.asarray(boot_draws)
    null = np.asarray(null_draws)
    extra_boot = np.asarray(s1_extra_boot)
    extra_null = np.asarray(s1_extra_null)
    quality = pd.DataFrame([{
        "n_requested": int(N_JOINT_RESAMPLES),
        "n_finite_marginal_bootstrap_rows": int(np.all(np.isfinite(boot), axis=1).sum()),
        "n_finite_marginal_joint_null_rows": int(np.all(np.isfinite(null), axis=1).sum()),
        "n_finite_study1_extra_bootstrap_rows": int(
            np.all(np.isfinite(extra_boot), axis=(1, 2)).sum()
        ),
        "n_finite_study1_extra_joint_null_rows": int(
            np.all(np.isfinite(extra_null), axis=(1, 2)).sum()
        ),
    }])
    return boot, null, extra_boot, extra_null, quality


# =============================================================================
# CROSS-STUDY PAIRING AND GLS POOLING
# =============================================================================


def pair_independent_studies(
    draws: np.ndarray,
    cross_study_pairing: np.ndarray,
) -> np.ndarray:
    values = np.asarray(draws, dtype=float)
    pairing = np.asarray(cross_study_pairing, dtype=int)
    if values.shape != (N_JOINT_RESAMPLES, len(EFFECT_KEYS)):
        raise ValueError(f"Unexpected draw matrix shape: {values.shape}")
    if sorted(pairing.tolist()) != list(range(N_JOINT_RESAMPLES)):
        raise ValueError("cross_study_pairing is not a permutation")

    output = values.copy()
    s2_columns = [
        EFFECT_INDEX[key]
        for key in EFFECT_KEYS
        if key[0] in STUDY2_DATASETS
    ]
    output[:, s2_columns] = values[pairing][:, s2_columns]
    return output


def regularize_covariance(covariance: np.ndarray) -> tuple[np.ndarray, float]:
    covariance = np.asarray(covariance, dtype=float)
    covariance = 0.5 * (covariance + covariance.T)
    eigenvalues, eigenvectors = np.linalg.eigh(covariance)
    positive = eigenvalues[eigenvalues > 0]
    reference = float(np.median(positive)) if len(positive) else 1.0
    floor = max(reference * 1e-8, 1e-12)
    clipped = np.maximum(eigenvalues, floor)
    regularized = (eigenvectors * clipped) @ eigenvectors.T
    return regularized, floor


def gls_pool(effect_z: np.ndarray, covariance: np.ndarray) -> dict[str, object]:
    z = np.asarray(effect_z, dtype=float)
    sigma, eigen_floor = regularize_covariance(covariance)
    inverse = np.linalg.pinv(sigma)
    ones = np.ones(len(z), dtype=float)
    denominator = float(ones @ inverse @ ones)
    if not np.isfinite(denominator) or denominator <= 0:
        raise ValueError("Invalid GLS pooling denominator")

    weights = (inverse @ ones) / denominator
    pooled = float(weights @ z)
    se = math.sqrt(1.0 / denominator)
    statistic = pooled / se if se > 0 else np.nan
    residual = z - pooled
    q_heterogeneity = float(residual @ inverse @ residual)
    df = len(z) - 1
    return {
        "pooled_z": pooled,
        "pooled_se_z": se,
        "z_statistic": statistic,
        "p_normal": float(2 * norm.sf(abs(statistic))) if np.isfinite(statistic) else np.nan,
        "weights": weights,
        "q_heterogeneity": q_heterogeneity,
        "df_heterogeneity": df,
        "p_heterogeneity": float(chi2.sf(q_heterogeneity, df)) if df > 0 else np.nan,
        "covariance_eigen_floor": eigen_floor,
        "covariance_used": sigma,
    }


def pool_columns(spec: dict[str, object]) -> list[int]:
    affect = str(spec["affect"])
    return [EFFECT_INDEX[(dataset, affect)] for dataset in spec["datasets"]]


def covariance_for_pool(
    boot_draws: np.ndarray,
    spec: dict[str, object],
) -> np.ndarray:
    columns = pool_columns(spec)
    values = np.asarray(boot_draws[:, columns], dtype=float)
    valid = np.all(np.isfinite(values), axis=1)
    if int(valid.sum()) < 10:
        raise ValueError(
            f"{spec['pool']} {spec['affect']}: too few finite bootstrap draws"
        )

    if not bool(spec["cross_study_block_diagonal"]):
        return np.cov(values[valid].T, ddof=1)

    datasets = list(spec["datasets"])
    covariance = np.zeros((len(datasets), len(datasets)), dtype=float)
    s1_pos = [i for i, dataset in enumerate(datasets) if dataset in STUDY1_DATASETS]
    s2_pos = [i for i, dataset in enumerate(datasets) if dataset in STUDY2_DATASETS]
    covariance[np.ix_(s1_pos, s1_pos)] = np.cov(values[valid][:, s1_pos].T, ddof=1)
    covariance[np.ix_(s2_pos, s2_pos)] = np.cov(values[valid][:, s2_pos].T, ddof=1)
    return covariance


def save_pool_covariance(
    spec: dict[str, object],
    covariance: np.ndarray,
) -> None:
    assert COV_DIR is not None
    labels = [DATASET_LABELS[d] for d in spec["datasets"]]
    stem = f"{spec['pool']}_{spec['affect']}"
    pd.DataFrame(covariance, index=labels, columns=labels).to_csv(
        COV_DIR / f"{stem}_bootstrap_covariance_fisher_z.csv"
    )
    denominator = np.sqrt(np.outer(np.diag(covariance), np.diag(covariance)))
    with np.errstate(divide="ignore", invalid="ignore"):
        correlation = covariance / denominator
    pd.DataFrame(correlation, index=labels, columns=labels).to_csv(
        COV_DIR / f"{stem}_bootstrap_correlation_fisher_z.csv"
    )


# =============================================================================
# RESULT TABLES
# =============================================================================


def build_dataset_results(
    M: ModuleType,
    observed_effects: np.ndarray,
    boot_draws: np.ndarray,
    null_draws: np.ndarray,
    observed_details: dict[tuple[str, str], dict[str, object]],
    block_lengths: dict[str, int],
) -> pd.DataFrame:
    rows = []
    for key in EFFECT_KEYS:
        dataset, affect = key
        index = EFFECT_INDEX[key]
        observed_z = float(observed_effects[index])
        boot = np.asarray(boot_draws[:, index], dtype=float)
        null = np.asarray(null_draws[:, index], dtype=float)
        ci_low_z, ci_high_z = quantile_ci(boot)
        rows.append({
            "study": DATASET_STUDY[dataset],
            "level": "stimulus_session",
            "target": DATASET_LABELS[dataset],
            "dataset": dataset,
            "analysis": "marginal",
            "affect": affect,
            "effect_fisher_z": observed_z,
            "estimate_partial_r": M.r_from_fisher_z(observed_z),
            "participant_bootstrap_ci95_low_r": M.r_from_fisher_z(ci_low_z),
            "participant_bootstrap_ci95_high_r": M.r_from_fisher_z(ci_high_z),
            "participant_bootstrap_ci95_low_z": ci_low_z,
            "participant_bootstrap_ci95_high_z": ci_high_z,
            "p_joint": two_sided_p(null, observed_z),
            "q_joint": np.nan,
            "fdr_family": "",
            "n_joint_resamples": int(np.isfinite(null).sum()),
            "n_windows": int(observed_details[key]["n_windows"]),
            "block_length": int(block_lengths[dataset]),
        })
    return pd.DataFrame(rows)


def build_pooled_results(
    M: ModuleType,
    observed_effects: np.ndarray,
    boot_draws: np.ndarray,
    null_draws: np.ndarray,
) -> pd.DataFrame:
    rows = []

    for spec in POOL_SPECS:
        columns = pool_columns(spec)
        observed_vector = np.asarray(observed_effects[columns], dtype=float)
        covariance = covariance_for_pool(boot_draws, spec)
        save_pool_covariance(spec, covariance)
        pooled = gls_pool(observed_vector, covariance)
        weights = np.asarray(pooled["weights"], dtype=float)

        boot_subset = np.asarray(boot_draws[:, columns], dtype=float)
        null_subset = np.asarray(null_draws[:, columns], dtype=float)
        boot_pooled = boot_subset @ weights
        null_pooled = null_subset @ weights
        ci_low_z, ci_high_z = quantile_ci(boot_pooled)
        observed_z = float(pooled["pooled_z"])

        row = {
            "study": spec["study"],
            "level": "pooled",
            "target": spec["pool"],
            "dataset": "|".join(spec["datasets"]),
            "analysis": "marginal",
            "affect": spec["affect"],
            "effect_fisher_z": observed_z,
            "estimate_partial_r": M.r_from_fisher_z(observed_z),
            "participant_bootstrap_ci95_low_r": M.r_from_fisher_z(ci_low_z),
            "participant_bootstrap_ci95_high_r": M.r_from_fisher_z(ci_high_z),
            "participant_bootstrap_ci95_low_z": ci_low_z,
            "participant_bootstrap_ci95_high_z": ci_high_z,
            "p_joint": two_sided_p(null_pooled, observed_z),
            "q_joint": np.nan,
            "fdr_family": "",
            "n_joint_resamples": int(np.isfinite(null_pooled).sum()),
            "n_windows": np.nan,
            "block_length": np.nan,
            "q_heterogeneity": pooled["q_heterogeneity"],
            "df_heterogeneity": pooled["df_heterogeneity"],
            "p_heterogeneity": pooled["p_heterogeneity"],
        }
        for dataset, weight in zip(spec["datasets"], weights):
            row[f"weight_{DATASET_LABELS[dataset]}"] = float(weight)
        rows.append(row)

    return pd.DataFrame(rows)


def build_study1_extra_dataset_results(
    M: ModuleType,
    observed_extra: np.ndarray,
    extra_boot: np.ndarray,
    extra_null: np.ndarray,
    observed_extra_details: dict[str, dict[str, dict[str, object]]],
    block_lengths: dict[str, int],
) -> pd.DataFrame:
    rows = []
    for family in S1_EXTRA_FAMILIES:
        fi = S1_EXTRA_INDEX[family]
        is_contrast = family == "marginal_valence_minus_arousal"
        for dataset in STUDY1_DATASETS:
            j = S1_DATASET_INDEX[dataset]
            observed_z = float(observed_extra[fi, j])
            boot = np.asarray(extra_boot[:, fi, j], dtype=float)
            null = np.asarray(extra_null[:, fi, j], dtype=float)
            ci_low_z, ci_high_z = quantile_ci(boot)
            rows.append({
                "study": "Study1",
                "level": "stimulus_session",
                "target": DATASET_LABELS[dataset],
                "dataset": dataset,
                "analysis": "contrast" if is_contrast else "conditional",
                "affect": "valence_minus_arousal" if is_contrast else "valence_given_arousal",
                "effect_fisher_z": observed_z,
                "estimate_partial_r": np.nan if is_contrast else M.r_from_fisher_z(observed_z),
                "participant_bootstrap_ci95_low_r": (
                    np.nan if is_contrast else M.r_from_fisher_z(ci_low_z)
                ),
                "participant_bootstrap_ci95_high_r": (
                    np.nan if is_contrast else M.r_from_fisher_z(ci_high_z)
                ),
                "participant_bootstrap_ci95_low_z": ci_low_z,
                "participant_bootstrap_ci95_high_z": ci_high_z,
                "p_joint": two_sided_p(null, observed_z),
                "q_joint": np.nan,
                "fdr_family": "",
                "n_joint_resamples": int(np.isfinite(null).sum()),
                "n_windows": int(observed_extra_details[family][dataset]["n_windows"]),
                "block_length": int(block_lengths[dataset]),
            })
    return pd.DataFrame(rows)


def build_study1_extra_pooled_results(
    M: ModuleType,
    observed_extra: np.ndarray,
    extra_boot: np.ndarray,
    extra_null: np.ndarray,
) -> pd.DataFrame:
    rows = []
    for family in S1_EXTRA_FAMILIES:
        fi = S1_EXTRA_INDEX[family]
        is_contrast = family == "marginal_valence_minus_arousal"
        observed_vector = np.asarray(observed_extra[fi], dtype=float)
        boot_family = np.asarray(extra_boot[:, fi, :], dtype=float)
        null_family = np.asarray(extra_null[:, fi, :], dtype=float)
        valid = np.all(np.isfinite(boot_family), axis=1)
        if int(valid.sum()) < 10:
            raise ValueError(f"{family}: too few finite Study-1 bootstrap draws")
        covariance = np.cov(boot_family[valid].T, ddof=1)

        # Save the sampling covariance used by GLS.
        assert COV_DIR is not None
        labels = [DATASET_LABELS[d] for d in STUDY1_DATASETS]
        pd.DataFrame(covariance, index=labels, columns=labels).to_csv(
            COV_DIR / f"pooledS1_{family}_bootstrap_covariance_fisher_z.csv"
        )

        pooled = gls_pool(observed_vector, covariance)
        weights = np.asarray(pooled["weights"], dtype=float)
        boot_pooled = boot_family @ weights
        null_pooled = null_family @ weights
        ci_low_z, ci_high_z = quantile_ci(boot_pooled)
        observed_z = float(pooled["pooled_z"])
        rows.append({
            "study": "Study1",
            "level": "pooled",
            "target": "pooledS1",
            "dataset": "|".join(STUDY1_DATASETS),
            "analysis": "contrast" if is_contrast else "conditional",
            "affect": "valence_minus_arousal" if is_contrast else "valence_given_arousal",
            "effect_fisher_z": observed_z,
            "estimate_partial_r": np.nan if is_contrast else M.r_from_fisher_z(observed_z),
            "participant_bootstrap_ci95_low_r": (
                np.nan if is_contrast else M.r_from_fisher_z(ci_low_z)
            ),
            "participant_bootstrap_ci95_high_r": (
                np.nan if is_contrast else M.r_from_fisher_z(ci_high_z)
            ),
            "participant_bootstrap_ci95_low_z": ci_low_z,
            "participant_bootstrap_ci95_high_z": ci_high_z,
            "p_joint": two_sided_p(null_pooled, observed_z),
            "q_joint": np.nan,
            "fdr_family": "",
            "n_joint_resamples": int(np.isfinite(null_pooled).sum()),
            "n_windows": np.nan,
            "block_length": np.nan,
            "q_heterogeneity": pooled["q_heterogeneity"],
            "df_heterogeneity": pooled["df_heterogeneity"],
            "p_heterogeneity": pooled["p_heterogeneity"],
            "weight_TP": float(weights[0]),
            "weight_DM": float(weights[1]),
            "weight_BD": float(weights[2]),
        })
    return pd.DataFrame(rows)


def apply_study1_extra_fdr(
    extra_dataset_results: pd.DataFrame,
    extra_pooled_results: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    extra_dataset_results = extra_dataset_results.copy()
    extra_pooled_results = extra_pooled_results.copy()

    for analysis in ["conditional", "contrast"]:
        mask = extra_dataset_results["analysis"].eq(analysis)
        q = bh_adjust(extra_dataset_results.loc[mask, "p_joint"].to_numpy(float))
        extra_dataset_results.loc[mask, "q_joint"] = q
        extra_dataset_results.loc[mask, "fdr_family"] = (
            f"Study1_{analysis}_stimulus_specific_3"
        )

        # One pooled test in each family: BH adjustment over one test leaves q=p.
        mask_pool = extra_pooled_results["analysis"].eq(analysis)
        extra_pooled_results.loc[mask_pool, "q_joint"] = extra_pooled_results.loc[
            mask_pool, "p_joint"
        ]
        extra_pooled_results.loc[mask_pool, "fdr_family"] = (
            f"Study1_{analysis}_pooled_single_test"
        )

    return extra_dataset_results, extra_pooled_results


def apply_marginal_fdr(
    dataset_results: pd.DataFrame,
    pooled_results: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    dataset_results = dataset_results.copy()
    pooled_results = pooled_results.copy()

    dataset_families = [
        (
            "Study1_stimulus_specific_marginal_6",
            dataset_results["study"].eq("Study1"),
        ),
        (
            "Study2_session_valence_2",
            dataset_results["study"].eq("Study2")
            & dataset_results["affect"].eq("valence"),
        ),
        (
            "Study2_session_fear_2",
            dataset_results["study"].eq("Study2")
            & dataset_results["affect"].eq("fear"),
        ),
    ]
    for family_name, mask in dataset_families:
        q = bh_adjust(dataset_results.loc[mask, "p_joint"].to_numpy(float))
        dataset_results.loc[mask, "q_joint"] = q
        dataset_results.loc[mask, "fdr_family"] = family_name

    # Study 1 pooled marginal valence/arousal form one two-test family.
    mask_s1 = pooled_results["target"].eq("pooledS1")
    pooled_results.loc[mask_s1, "q_joint"] = bh_adjust(
        pooled_results.loc[mask_s1, "p_joint"].to_numpy(float)
    )
    pooled_results.loc[mask_s1, "fdr_family"] = "Study1_pooled_marginal_2"

    # Final manuscript specification: pooled Study-2 valence and fear are
    # separate planned single-test families, hence q_joint = p_joint.
    for affect in ("valence", "fear"):
        mask = pooled_results["target"].eq("pooledS2") & pooled_results["affect"].eq(affect)
        pooled_results.loc[mask, "q_joint"] = pooled_results.loc[mask, "p_joint"]
        pooled_results.loc[mask, "fdr_family"] = f"Study2_pooled_{affect}_single_test"

    # pooledfive valence is also one planned pooled test, hence q_joint = p_joint.
    mask_five = pooled_results["target"].eq("pooledfive")
    pooled_results.loc[mask_five, "q_joint"] = pooled_results.loc[mask_five, "p_joint"]
    pooled_results.loc[mask_five, "fdr_family"] = "AllFive_pooled_valence_single_test"

    return dataset_results, pooled_results


def build_complete_report(
    dataset_results: pd.DataFrame,
    pooled_results: pd.DataFrame,
    extra_dataset_results: pd.DataFrame,
    extra_pooled_results: pd.DataFrame,
) -> pd.DataFrame:
    common_columns = [
        "study",
        "analysis",
        "level",
        "target",
        "dataset",
        "affect",
        "estimate_partial_r",
        "participant_bootstrap_ci95_low_r",
        "participant_bootstrap_ci95_high_r",
        "effect_fisher_z",
        "participant_bootstrap_ci95_low_z",
        "participant_bootstrap_ci95_high_z",
        "p_joint",
        "q_joint",
        "fdr_family",
        "n_joint_resamples",
        "n_windows",
        "block_length",
    ]
    combined = pd.concat(
        [
            dataset_results.reindex(columns=common_columns),
            pooled_results.reindex(columns=common_columns),
            extra_dataset_results.reindex(columns=common_columns),
            extra_pooled_results.reindex(columns=common_columns),
        ],
        ignore_index=True,
    )

    order = []
    # Marginal Study 1: valence then arousal; pooled first within each affect.
    for affect in ["valence", "arousal"]:
        order.append(("Study1", "marginal", "pooled", "pooledS1", affect))
        for target in ["TP", "DM", "BD"]:
            order.append(("Study1", "marginal", "stimulus_session", target, affect))

    # Marginal Study 2: valence then fear.
    for affect in ["valence", "fear"]:
        order.append(("Study2", "marginal", "pooled", "pooledS2", affect))
        for target in ["H1", "H2"]:
            order.append(("Study2", "marginal", "stimulus_session", target, affect))

    # Cross-study planned marginal valence pool.
    order.append(("Study1+Study2", "marginal", "pooled", "pooledfive", "valence"))

    # Study-1-only conditional valence.
    order.append(("Study1", "conditional", "pooled", "pooledS1", "valence_given_arousal"))
    for target in ["TP", "DM", "BD"]:
        order.append(("Study1", "conditional", "stimulus_session", target, "valence_given_arousal"))

    # Study-1-only valence-minus-arousal contrast.
    order.append(("Study1", "contrast", "pooled", "pooledS1", "valence_minus_arousal"))
    for target in ["TP", "DM", "BD"]:
        order.append(("Study1", "contrast", "stimulus_session", target, "valence_minus_arousal"))

    rank = {key: i for i, key in enumerate(order)}
    combined["_order"] = [
        rank.get((row.study, row.analysis, row.level, row.target, row.affect), 999)
        for row in combined.itertuples(index=False)
    ]
    combined = combined.sort_values("_order").drop(columns="_order").reset_index(drop=True)
    return combined


# =============================================================================
# MAIN
# =============================================================================


def main() -> None:
    global OUT_DIR, DRAW_DIR, COV_DIR

    _require_participant_config()
    embedded_paths = _materialize_embedded_scripts()

    print_section("IMPORT EMBEDDED DEPENDENCY-AWARE SOURCE PIPELINES")
    M = _load_python_module(
        embedded_paths["Study1_group_median_meta_analysis_joint_sampling_temporal.py"],
        "study1_group_median_meta_helpers_allaffects",
    )
    S1 = _load_python_module(
        embedded_paths["Study1_DMN_independent_modalities.py"],
        "study1_independent_modalities_source_allaffects",
    )
    S2 = _load_python_module(
        embedded_paths["Study2_DMN_matched_modalities.py"],
        "study2_matched_modalities_source_allaffects",
    )
    validate_sources(M, S1, S2)
    M.PROGRESS_EVERY = PROGRESS_EVERY

    OUT_DIR = Path(getattr(S1, "RESULTS_ROOT", S1.BASE_DIR)) / "group_median" / "AllFive_group_median_ALL_AFFECTS_joint_sampling_temporal"
    DRAW_DIR = OUT_DIR / "resampling_draws"
    COV_DIR = OUT_DIR / "covariance"
    for directory in [OUT_DIR, DRAW_DIR, COV_DIR]:
        directory.mkdir(parents=True, exist_ok=True)

    print_section("PREPARE STRICTLY ALIGNED STUDY 1 AND STUDY 2 CACHES")
    s1_prepared = S1.prepare_all_data()
    s2_prepared = S2.prepare_all_data()
    all_data = AnalysisData(s1_prepared=s1_prepared, s2_prepared=s2_prepared)

    audit = validate_prepared_data(S1, all_data)
    audit.to_csv(OUT_DIR / "AllAffects_group_median_alignment_and_sample_audit.csv", index=False)

    print_section("PRECOMPUTE SORTED DYAD VALUES FOR EXACT WEIGHTED MEDIANS")
    sorted_caches = prepare_sorted_caches(M, S1, all_data)

    observed_neural = {
        dataset: M.observed_median_from_sorted(sorted_caches["neural"][dataset])
        for dataset in DATASETS
    }
    observed_behavior = {
        dataset: {
            affect: M.observed_median_from_sorted(sorted_caches["behavior"][dataset][affect])
            for affect in affects_for_dataset(dataset)
        }
        for dataset in DATASETS
    }
    all_data.observed_neural = observed_neural
    all_data.observed_behavior = observed_behavior

    print_section("OBSERVED DATASET x AFFECT EFFECTS")
    observed_effects, observed_details, observed_tables = calculate_effects(M, all_data)
    observed_extra, observed_extra_details = calculate_study1_extra_effects(M, observed_tables)

    observed_rows = []
    for key in EFFECT_KEYS:
        dataset, affect = key
        index = EFFECT_INDEX[key]
        observed_rows.append({
            "study": DATASET_STUDY[dataset],
            "dataset": dataset,
            "target": DATASET_LABELS[dataset],
            "affect": affect,
            "effect_fisher_z": observed_effects[index],
            "estimate_partial_r": M.r_from_fisher_z(observed_effects[index]),
            "n_windows": observed_details[key]["n_windows"],
        })
    pd.DataFrame(observed_rows).to_csv(
        OUT_DIR / "AllAffects_group_median_observed_dataset_effects.csv",
        index=False,
    )

    observed_extra_rows = []
    for family in S1_EXTRA_FAMILIES:
        fi = S1_EXTRA_INDEX[family]
        for dataset in STUDY1_DATASETS:
            j = S1_DATASET_INDEX[dataset]
            is_contrast = family == "marginal_valence_minus_arousal"
            observed_extra_rows.append({
                "study": "Study1",
                "family": family,
                "dataset": dataset,
                "target": DATASET_LABELS[dataset],
                "effect_fisher_z_or_delta_z": observed_extra[fi, j],
                "estimate_partial_r": (
                    np.nan if is_contrast else M.r_from_fisher_z(observed_extra[fi, j])
                ),
            })
    pd.DataFrame(observed_extra_rows).to_csv(
        OUT_DIR / "Study1_conditional_contrast_observed_effects.csv",
        index=False,
    )

    print_section("ACF-BASED COMMON BLOCK LENGTHS WITHIN DATASET")
    block_lengths, block_table = prepare_block_lengths(
        M,
        observed_details,
        observed_tables,
    )
    block_table.to_csv(
        OUT_DIR / "AllAffects_group_median_block_lengths.csv",
        index=False,
    )
    print(block_table.to_string(index=False))

    print_section("GENERATE / LOAD JOINT PARTICIPANT AND TEMPORAL PLAN")
    plan = generate_joint_plan(M, S1, all_data, block_lengths)

    print_section("EXACT PARTICIPANT BOOTSTRAP + TEMPORAL BLOCK NULL")
    boot_raw, null_raw, extra_boot, extra_null, quality = run_joint_resampling(
        M,
        all_data,
        sorted_caches,
        plan,
        block_lengths,
    )
    quality.to_csv(
        OUT_DIR / "AllAffects_group_median_joint_resampling_quality.csv",
        index=False,
    )

    # Independently re-pair Study-2 rows with Study-1 rows while keeping every
    # Study-2 session/affect column together. This leaves within-study results
    # unchanged but gives the all-five pooled CI/null an explicit independent-
    # study construction.
    boot = pair_independent_studies(boot_raw, plan["cross_study_pairing"])
    null = pair_independent_studies(null_raw, plan["cross_study_pairing"])
    np.save(DRAW_DIR / "AllAffects_bootstrap_effects_crossstudy_paired.npy", boot)
    np.save(DRAW_DIR / "AllAffects_joint_null_crossstudy_paired.npy", null)

    print_section("DATASET/SESSION-SPECIFIC RESULTS")
    dataset_results = build_dataset_results(
        M,
        observed_effects,
        boot,
        null,
        observed_details,
        block_lengths,
    )

    print_section("POOLED S1, POOLED S2, AND ALL-FIVE VALENCE RESULTS")
    pooled_results = build_pooled_results(
        M,
        observed_effects,
        boot,
        null,
    )

    dataset_results, pooled_results = apply_marginal_fdr(
        dataset_results,
        pooled_results,
    )

    print_section("STUDY 1 CONDITIONAL VALENCE AND VALENCE-AROUSAL CONTRAST")
    extra_dataset_results = build_study1_extra_dataset_results(
        M,
        observed_extra,
        extra_boot,
        extra_null,
        observed_extra_details,
        block_lengths,
    )
    extra_pooled_results = build_study1_extra_pooled_results(
        M,
        observed_extra,
        extra_boot,
        extra_null,
    )
    extra_dataset_results, extra_pooled_results = apply_study1_extra_fdr(
        extra_dataset_results,
        extra_pooled_results,
    )

    complete_report = build_complete_report(
        dataset_results,
        pooled_results,
        extra_dataset_results,
        extra_pooled_results,
    )

    dataset_results.to_csv(
        OUT_DIR / "AllAffects_DATASET_SESSION_results.csv",
        index=False,
    )
    pooled_results.to_csv(
        OUT_DIR / "AllAffects_POOLED_results.csv",
        index=False,
    )
    extra_dataset_results.to_csv(
        OUT_DIR / "Study1_CONDITIONAL_CONTRAST_dataset_results.csv",
        index=False,
    )
    extra_pooled_results.to_csv(
        OUT_DIR / "Study1_CONDITIONAL_CONTRAST_pooled_results.csv",
        index=False,
    )
    complete_report.to_csv(
        OUT_DIR / "AllAffects_COMPLETE_results_for_table.csv",
        index=False,
    )

    metadata = {
        "analysis": "supplementary group-median temporal coupling across Study 1 and Study 2; conditional/contrast restricted to Study 1",
        "effect_keys": [[dataset, affect] for dataset, affect in EFFECT_KEYS],
        "pool_specs": POOL_SPECS,
        "study1_alignment_version": getattr(S1, "CHEN_ALIGNMENT_POLICY_VERSION", None),
        "study2_alignment_version": getattr(S2, "CHEN_ALIGNMENT_POLICY_VERSION", None),
        "covariates": MODEL_COVARIATES,
        "dataset_effect": (
            "partial correlation across windows between standardized group-median "
            "neural ISC and group-median affective ISC after nuisance residualization; "
            "Fisher-z transformed before pooling"
        ),
        "pooling": "covariance-aware fixed-effect GLS on Fisher-z effects",
        "allfive_covariance": "explicit block diagonal 3x3 Study-1 + 2x2 Study-2",
        "participant_ci": (
            "percentile 95% CI from neural+behavior participant-bootstrap pooled draws "
            "using fixed observed GLS weights"
        ),
        "joint_p": (
            "two-sided p from neural+behavior participant-bootstrap plus intact-block temporal-permutation null"
        ),
        "block_lengths": block_lengths,
        "fdr_families": {
            "Study1_pooled": "2 marginal effects (valence, arousal)",
            "Study1_stimulus_specific": "6 marginal effects (3 movies x 2 affects)",
            "Study2_pooled_valence": "single pooled valence test; q=p",
            "Study2_pooled_fear": "single pooled fear test; q=p",
            "Study2_session_valence": "2 tests (H1, H2)",
            "Study2_session_fear": "2 tests (H1, H2)",
            "Study1_conditional_stimulus_specific": "3 tests (TP, DM, BD)",
            "Study1_conditional_pooled": "single pooledS1 test; q=p",
            "Study1_contrast_stimulus_specific": "3 tests (TP, DM, BD)",
            "Study1_contrast_pooled": "single pooledS1 test; q=p",
            "pooledfive_valence": "single planned pooled test; q=p",
        },
        "n_joint_resamples": int(N_JOINT_RESAMPLES),
        "random_seed": int(RANDOM_SEED),
        "scope": (
            "complementary group-median trajectory analysis; not a replacement for "
            "the primary dyad-level two-stage mixed-effects analysis"
        ),
    }
    save_json(metadata, OUT_DIR / "AllAffects_group_median_metadata.json")

    print("\n" + complete_report.to_string(index=False))
    print_section("COMPLETE")
    print(f"Output directory: {OUT_DIR}")
    print("Primary table-ready file: AllAffects_COMPLETE_results_for_table.csv")


if __name__ == "__main__":
    main()
